cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>
#include <cstdint>

using namespace cute;

// ---------------------------------------------------------------------
// Kernel 1: per-channel reduction (sum, sum of squares) over N,H,W
// ---------------------------------------------------------------------
__global__ void bn_reduce_kernel(const float* __restrict__ X,
                                  int N, int C, int H, int W,
                                  double* __restrict__ sum,
                                  double* __restrict__ sumsq)
{
  int c = blockIdx.x;
  int HW = H * W;
  int64_t strideN = (int64_t)C * HW;

  // View of channel c: shape (N, HW), stride (C*H*W, 1)
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                         make_shape(N, HW),
                         make_stride(strideN, Int<1>{}));

  int64_t total  = (int64_t)N * HW;
  int64_t tid    = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.y * blockDim.x;

  double local_sum   = 0.0;
  double local_sumsq = 0.0;

  for (int64_t idx = tid; idx < total; idx += stride) {
    int n  = (int)(idx / HW);
    int hw = (int)(idx % HW);
    float v = mX(n, hw);
    local_sum   += (double)v;
    local_sumsq += (double)v * (double)v;
  }

  __shared__ double s_sum[256];
  __shared__ double s_sumsq[256];
  int t = threadIdx.x;
  s_sum[t]   = local_sum;
  s_sumsq[t] = local_sumsq;
  __syncthreads();

  for (int off = blockDim.x / 2; off > 0; off >>= 1) {
    if (t < off) {
      s_sum[t]   += s_sum[t + off];
      s_sumsq[t] += s_sumsq[t + off];
    }
    __syncthreads();
  }

  if (t == 0) {
    atomicAdd(&sum[c], s_sum[0]);
    atomicAdd(&sumsq[c], s_sumsq[0]);
  }
}

// ---------------------------------------------------------------------
// Kernel 2a: finalize statistics for training mode, update running stats
// ---------------------------------------------------------------------
__global__ void bn_finalize_train_kernel(const double* __restrict__ sum,
                                          const double* __restrict__ sumsq,
                                          int C, int64_t count,
                                          float eps, float momentum,
                                          float* __restrict__ running_mean,
                                          float* __restrict__ running_var,
                                          float* __restrict__ mean_out,
                                          float* __restrict__ invstd_out)
{
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;

  double m   = sum[c] / (double)count;
  double var = sumsq[c] / (double)count - m * m;
  if (var < 0.0) var = 0.0;

  mean_out[c]   = (float)m;
  invstd_out[c] = (float)(1.0 / sqrt(var + (double)eps));

  double unbiased_var = (count > 1) ? var * (double)count / (double)(count - 1) : var;

  running_mean[c] = (float)((1.0 - (double)momentum) * (double)running_mean[c] + (double)momentum * m);
  running_var[c]  = (float)((1.0 - (double)momentum) * (double)running_var[c]  + (double)momentum * unbiased_var);
}

// ---------------------------------------------------------------------
// Kernel 2b: finalize statistics for eval mode (use running stats)
// ---------------------------------------------------------------------
__global__ void bn_finalize_eval_kernel(const float* __restrict__ running_mean,
                                         const float* __restrict__ running_var,
                                         int C, float eps,
                                         float* __restrict__ mean_out,
                                         float* __restrict__ invstd_out)
{
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;
  mean_out[c]   = running_mean[c];
  invstd_out[c] = 1.0f / sqrtf(running_var[c] + eps);
}

// ---------------------------------------------------------------------
// Kernel 3: normalize + affine transform (elementwise)
// ---------------------------------------------------------------------
__global__ void bn_normalize_kernel(const float* __restrict__ X,
                                     float* __restrict__ Y,
                                     const float* __restrict__ weight,
                                     const float* __restrict__ bias,
                                     const float* __restrict__ mean,
                                     const float* __restrict__ invstd,
                                     int N, int C, int H, int W)
{
  int64_t HW = (int64_t)H * W;
  int64_t NC = (int64_t)N * C;
  int64_t total = NC * HW;

  // Flatten (N,C) outer dims: contiguous with stride HW between them.
  auto mX = make_tensor(make_gmem_ptr(X), make_shape(NC, HW), make_stride(HW, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y), make_shape(NC, HW), make_stride(HW, Int<1>{}));

  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.x * blockDim.x;

  for (; idx < total; idx += stride) {
    int64_t nc = idx / HW;
    int64_t hw = idx % HW;
    int c = (int)(nc % C);

    float v = mX(nc, hw);
    float y = (v - mean[c]) * invstd[c] * weight[c] + bias[c];
    mY(nc, hw) = y;
  }
}
// ---------------------------------------------------------------------
// Kernel 3b: normalize + affine transform (vectorized float4 elementwise)
// Valid when HW is divisible by 4 (contiguous NCHW layout guarantees
// that 4 consecutive elements along the last dim belong to the same
// (n, c) slice, so per-channel mean/invstd/weight/bias apply uniformly).
// ---------------------------------------------------------------------
__global__ void bn_normalize_kernel_vec4(const float4* __restrict__ X,
                                          float4* __restrict__ Y,
                                          const float* __restrict__ weight,
                                          const float* __restrict__ bias,
                                          const float* __restrict__ mean,
                                          const float* __restrict__ invstd,
                                          int64_t NC, int64_t HW4, int C)
{
  int64_t total  = NC * HW4;
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.x * blockDim.x;
  for (; idx < total; idx += stride) {
    int64_t nc = idx / HW4;
    int c = (int)(nc % C);
    float m  = mean[c];
    float is = invstd[c];
    float w  = weight[c];
    float b  = bias[c];
    float4 v = X[idx];
    float4 out;
    out.x = (v.x - m) * is * w + b;
    out.y = (v.y - m) * is * w + b;
    out.z = (v.z - m) * is * w + b;
    out.w = (v.w - m) * is * w + b;
    Y[idx] = out;
  }
}

// ---------------------------------------------------------------------
// Host wrapper
// ---------------------------------------------------------------------
torch::Tensor batchnorm2d_forward(torch::Tensor x,
