  auto x_c = x.contiguous();
  int N = (int)x_c.size(0);
  int C = (int)x_c.size(1);
  int H = (int)x_c.size(2);
  int W = (int)x_c.size(3);

  auto y = torch::empty_like(x_c);

  auto opts_f = x.options();
  auto opts_d = x.options().dtype(at::kDouble);

  auto mean_buf   = torch::empty({C}, opts_f);
  auto invstd_buf = torch::empty({C}, opts_f);

  auto weight_c = weight.contiguous();
  auto bias_c   = bias.contiguous();
  auto running_mean_c = running_mean.contiguous();
  auto running_var_c  = running_var.contiguous();

  bool rm_same = running_mean_c.data_ptr() == running_mean.data_ptr();
  bool rv_same = running_var_c.data_ptr() == running_var.data_ptr();

