    float is = invstd[c];
    float w  = weight[c];
    float b  = bias[c];
    float4 v = X[idx];
    float4 out;
    out.x = (v.x - m) * is * w + b;
    out.y = (v.y - m) * is * w + b;
    out.z = (v.z - m) * is * w + b;
    out.w = (v.w - m) * is * w + b;
    Y[idx] = out;
  }
}

