cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <algorithm>
#include <cstdint>

using namespace cute;

// ---------------------------------------------------------------------
// Kernel 1: per-channel reduction (sum, sum of squares) over N,H,W
// ---------------------------------------------------------------------
__global__ void bn_reduce_kernel(const float* __restrict__ X,
                                  int N, int C, int H, int W,
                                  double* __restrict__ sum,
                                  double* __restrict__ sumsq)
{
  int c = blockIdx.x;
  int HW = H * W;
  int64_t strideN = (int64_t)C * HW;

  // View of channel c: shape (N, HW), stride (C*H*W, 1)
  auto mX = make_tensor(make_gmem_ptr(X + (int64_t)c * HW),
                         make_shape(N, HW),
                         make_stride(strideN, Int<1>{}));

  int64_t total  = (int64_t)N * HW;
  int64_t tid    = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.y * blockDim.x;

  double local_sum   = 0.0;
  double local_sumsq = 0.0;

  for (int64_t idx = tid; idx < total; idx += stride) {
    int n  = (int)(idx / HW);
    int hw = (int)(idx % HW);
    float v = mX(n, hw);
    local_sum   += (double)v;
    local_sumsq += (double)v * (double)v;
  }

  __shared__ double s_sum[256];
  __shared__ double s_sumsq[256];
  int t = threadIdx.x;
  s_sum[t]   = local_sum;
  s_sumsq[t] = local_sumsq;
  __syncthreads();

  for (int off = blockDim.x / 2; off > 0; off >>= 1) {
    if (t < off) {
      s_sum[t]   += s_sum[t + off];
      s_sumsq[t] += s_sumsq[t + off];
    }
    __syncthreads();
  }

  if (t == 0) {
    atomicAdd(&sum[c], s_sum[0]);
    atomicAdd(&sumsq[c], s_sumsq[0]);
  }
}

// ---------------------------------------------------------------------
// Kernel 2a: finalize statistics for training mode, update running stats
// ---------------------------------------------------------------------
__global__ void bn_finalize_train_kernel(const double* __restrict__ sum,
                                          const double* __restrict__ sumsq,
                                          int C, int64_t count,
                                          float eps, float momentum,
                                          float* __restrict__ running_mean,
                                          float* __restrict__ running_var,
                                          float* __restrict__ mean_out,
                                          float* __restrict__ invstd_out)
{
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;

  double m   = sum[c] / (double)count;
  double var = sumsq[c] / (double)count - m * m;
  if (var < 0.0) var = 0.0;

  mean_out[c]   = (float)m;
  invstd_out[c] = (float)(1.0 / sqrt(var + (double)eps));

  double unbiased_var = (count > 1) ? var * (double)count / (double)(count - 1) : var;

  running_mean[c] = (float)((1.0 - (double)momentum) * (double)running_mean[c] + (double)momentum * m);
  running_var[c]  = (float)((1.0 - (double)momentum) * (double)running_var[c]  + (double)momentum * unbiased_var);
}

// ---------------------------------------------------------------------
// Kernel 2b: finalize statistics for eval mode (use running stats)
// ---------------------------------------------------------------------
__global__ void bn_finalize_eval_kernel(const float* __restrict__ running_mean,
                                         const float* __restrict__ running_var,
                                         int C, float eps,
                                         float* __restrict__ mean_out,
                                         float* __restrict__ invstd_out)
{
  int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;
  mean_out[c]   = running_mean[c];
  invstd_out[c] = 1.0f / sqrtf(running_var[c] + eps);
}

// ---------------------------------------------------------------------
// Kernel 3: normalize + affine transform (elementwise)
// ---------------------------------------------------------------------
__global__ void bn_normalize_kernel(const float* __restrict__ X,
                                     float* __restrict__ Y,
                                     const float* __restrict__ weight,
                                     const float* __restrict__ bias,
                                     const float* __restrict__ mean,
                                     const float* __restrict__ invstd,
                                     int N, int C, int H, int W)
{
  int64_t HW = (int64_t)H * W;
  int64_t NC = (int64_t)N * C;
  int64_t total = NC * HW;

  // Flatten (N,C) outer dims: contiguous with stride HW between them.
  auto mX = make_tensor(make_gmem_ptr(X), make_shape(NC, HW), make_stride(HW, Int<1>{}));
  auto mY = make_tensor(make_gmem_ptr(Y), make_shape(NC, HW), make_stride(HW, Int<1>{}));

  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)gridDim.x * blockDim.x;

  for (; idx < total; idx += stride) {
    int64_t nc = idx / HW;
    int64_t hw = idx % HW;
    int c = (int)(nc % C);

    float v = mX(nc, hw);
    float y = (v - mean[c]) * invstd[c] * weight[c] + bias[c];
    mY(nc, hw) = y;
  }
}

// ---------------------------------------------------------------------
// Host wrapper
// ---------------------------------------------------------------------
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
  TORCH_CHECK(running_mean.is_cuda() && running_var.is_cuda(), "running stats must be CUDA");

  auto x_c = x.contiguous();
  int N = (int)x_c.size(0);
  int C = (int)x_c.size(1);
  int H = (int)x_c.size(2);
  int W = (int)x_c.size(3);

  auto y = torch::empty_like(x_c);

  auto opts_f = x.options();
  auto opts_d = x.options().dtype(at::kDouble);

  auto mean_buf   = torch::empty({C}, opts_f);
  auto invstd_buf = torch::empty({C}, opts_f);

  auto weight_c = weight.contiguous();
  auto bias_c   = bias.contiguous();
  auto running_mean_c = running_mean.contiguous();
  auto running_var_c  = running_var.contiguous();

  bool rm_same = running_mean_c.data_ptr() == running_mean.data_ptr();
  bool rv_same = running_var_c.data_ptr() == running_var.data_ptr();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (training) {
    auto sum_buf   = torch::zeros({C}, opts_d);
    auto sumsq_buf = torch::zeros({C}, opts_d);

    int64_t HW = (int64_t)H * W;
    int64_t total_per_c = (int64_t)N * HW;
    int block = 256;
    int64_t bpc64 = std::min<int64_t>(64, (total_per_c + block - 1) / block);
    int blocksPerChannel = (int)std::max<int64_t>(1, bpc64);

    dim3 grid((unsigned)C, (unsigned)blocksPerChannel);
    bn_reduce_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(), N, C, H, W,
        sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>());

    int64_t count = (int64_t)N * H * W;
    int fb = 128;
    int fg = (C + fb - 1) / fb;
    bn_finalize_train_kernel<<<fg, fb, 0, stream>>>(
        sum_buf.data_ptr<double>(), sumsq_buf.data_ptr<double>(), C, count,
        (float)eps, (float)momentum,
        running_mean_c.data_ptr<float>(), running_var_c.data_ptr<float>(),
        mean_buf.data_ptr<float>(), invstd_buf.data_ptr<float>());
  } else {
    int fb = 128;
    int fg = (C + fb - 1) / fb;
    bn_finalize_eval_kernel<<<fg, fb, 0, stream>>>(
        running_mean_c.data_ptr<float>(), running_var_c.data_ptr<float>(), C, (float)eps,
        mean_buf.data_ptr<float>(), invstd_buf.data_ptr<float>());
  }

  int64_t total = (int64_t)N * C * H * W;
  int nblock = 256;
  int64_t ngrid64 = (total + nblock - 1) / nblock;
  ngrid64 = std::min<int64_t>(ngrid64, 65535LL * 256LL);
  int ngrid = (int)std::max<int64_t>(1, ngrid64);

  bn_normalize_kernel<<<ngrid, nblock, 0, stream>>>(
      x_c.data_ptr<float>(), y.data_ptr<float>(),
      weight_c.data_ptr<float>(), bias_c.data_ptr<float>(),
      mean_buf.data_ptr<float>(), invstd_buf.data_ptr<float>(),
      N, C, H, W);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "batchnorm2d kernel launch failed: ", cudaGetErrorString(err));

  if (training) {
    if (!rm_same) running_mean.copy_(running_mean_c);
    if (!rv_same) running_var.copy_(running_var_c);
  }

  return y;
}
